package com.ayindebuild.app.services\n\nimport android.content.Context\nimport kotlinx.coroutines.*\nimport java.net.HttpURLConnection\nimport java.net.URL\nimport org.json.JSONObject\n\nclass LLMService(private val context: Context) {\n    private val baseUrl = \"http://localhost:11434\"\n    private val scope = CoroutineScope(Dispatchers.Main + Job())\n\n    fun downloadModel(modelName: String, onProgress: (Int) -> Unit) {\n        scope.launch(Dispatchers.IO) {\n            try {\n                val url = URL(\"$baseUrl/api/pull\")\n                val connection = url.openConnection() as HttpURLConnection\n                connection.requestMethod = \"POST\"\n                connection.setRequestProperty(\"Content-Type\", \"application/json\")\n                connection.doOutput = true\n\n                val body = JSONObject()\n                body.put(\"name\", modelName)\n                body.put(\"stream\", true)\n\n                connection.outputStream.write(body.toString().toByteArray())\n                connection.outputStream.close()\n\n                val reader = connection.inputStream.bufferedReader()\n                var line: String? = reader.readLine()\n                var progress = 0\n\n                while (line != null) {\n                    try {\n                        val json = JSONObject(line)\n                        if (json.has(\"completed\") && json.has(\"total\")) {\n                            val completed = json.getLong(\"completed\")\n                            val total = json.getLong(\"total\")\n                            progress = (completed * 100 / total).toInt()\n                            withContext(Dispatchers.Main) {\n                                onProgress(progress)\n                            }\n                        }\n                    } catch (e: Exception) {\n                        e.printStackTrace()\n                    }\n                    line = reader.readLine()\n                }\n\n                reader.close()\n                connection.disconnect()\n            } catch (e: Exception) {\n                e.printStackTrace()\n            }\n        }\n    }\n\n    fun chat(prompt: String, onResponse: (String) -> Unit) {\n        scope.launch(Dispatchers.IO) {\n            try {\n                val url = URL(\"$baseUrl/api/generate\")\n                val connection = url.openConnection() as HttpURLConnection\n                connection.requestMethod = \"POST\"\n                connection.setRequestProperty(\"Content-Type\", \"application/json\")\n                connection.doOutput = true\n\n                val body = JSONObject()\n                body.put(\"model\", \"llama2\")\n                body.put(\"prompt\", prompt)\n                body.put(\"stream\", false)\n\n                connection.outputStream.write(body.toString().toByteArray())\n                connection.outputStream.close()\n\n                val response = connection.inputStream.bufferedReader().readText()\n                val json = JSONObject(response)\n                val responseText = json.optString(\"response\", \"No response\")\n\n                withContext(Dispatchers.Main) {\n                    onResponse(responseText)\n                }\n\n                connection.disconnect()\n            } catch (e: Exception) {\n                withContext(Dispatchers.Main) {\n                    onResponse(\"Error: ${e.message}\")\n                }\n            }\n        }\n    }\n\n    fun listModels(onModels: (List<String>) -> Unit) {\n        scope.launch(Dispatchers.IO) {\n            try {\n                val url = URL(\"$baseUrl/api/tags\")\n                val connection = url.openConnection() as HttpURLConnection\n                connection.requestMethod = \"GET\"\n\n                val response = connection.inputStream.bufferedReader().readText()\n                val json = JSONObject(response)\n                val models = mutableListOf<String>()\n\n                if (json.has(\"models\")) {\n                    val modelArray = json.getJSONArray(\"models\")\n                    for (i in 0 until modelArray.length()) {\n                        val model = modelArray.getJSONObject(i)\n                        models.add(model.optString(\"name\", \"unknown\"))\n                    }\n                }\n\n                withContext(Dispatchers.Main) {\n                    onModels(models)\n                }\n\n                connection.disconnect()\n            } catch (e: Exception) {\n                withContext(Dispatchers.Main) {\n                    onModels(emptyList())\n                }\n            }\n        }\n    }\n\n    fun destroy() {\n        scope.cancel()\n    }\n}\n